mapper.select:
select id, name, type, lat, lng, address, city_code, status, audit_status, merchant_id, template_id
from roam_poi
where lat between #{minLat} and #{maxLat} and lng between #{minLng} and #{maxLng}

select id, name, type, lat, lng, address, description, cover_img, city_code, status, audit_status, merchant_id, template_id
from roam_poi
where id in #{id}

select distinct name from cms_topic
where del_flag = 0 and topic_type = 1
  and name in #{n}
